const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const orderId = '#W7231611';
const itemIds = JSON.stringify(['3301828484']);
const newItemIds = JSON.stringify(['7389318502']);
const paymentMethodId = 'credit_card_9958253';
const priceDiff = 0.46;  // 23.91 - 23.45

