const result = db.prepare(\`
  UPDATE orders
  SET status = 'exchange requested',
      exchange_items = ?,
      exchange_new_items = ?,
      exchange_payment_method_id = ?,
      exchange_price_difference = ?
  WHERE order_id = ?
\`).run(itemIds, newItemIds, paymentMethodId, priceDiff, orderId);

console.log('Rows updated:', result.changes);

// Verify the update
